<?php
function borrow_outstanding($r){return (int)$r['qty']-(int)$r['returned_qty']-(int)$r['converted_qty'];}
function borrow_get($id,$lock=false){$q=db()->prepare('SELECT b.*,p.name,p.master_sku FROM borrowed_items b JOIN products p ON p.id=b.product_id WHERE b.id=?'.($lock?' FOR UPDATE':''));$q->execute([$id]);$r=$q->fetch();if(!$r)throw new Exception('Borrow record not found.');return $r;}
function borrow_refresh_status($id){$r=borrow_get($id);$status=borrow_outstanding($r)>0?'Outstanding':((int)$r['converted_qty']>0?'Closed / Converted':'Returned');db()->prepare('UPDATE borrowed_items SET status=? WHERE id=?')->execute([$status,$id]);}
function borrow_issue($input){
 if(array_key_exists('items',$input))return borrow_issue_multiple($input);
 return process_transaction(function()use($input){
  $pid=(int)($input['product_id']??0);$platform=stock_platform($input['source_platform']??'');$qty=whole_number($input['qty']??'','Quantity',1);$date=process_date($input['txn_date']??'');$due=$input['due_date']??'';$d=DateTime::createFromFormat('!Y-m-d',$due);if(!$d||$d->format('Y-m-d')!==$due||$due<$date)throw new Exception('Due date must be on or after the issue date.');
  $borrower=trim($input['borrower']??'');if($borrower===''||strlen($borrower)>150)throw new Exception('Enter the borrower name (up to 150 characters).');$reason=process_reason($input['reason']??'');$ref=trim($input['borrow_ref']??'');if(!preg_match('/^[A-Za-z0-9_-]{6,100}$/',$ref))throw new Exception('Invalid borrow reference. Refresh the form.');
  $q=db()->prepare('SELECT id FROM products WHERE id=? AND active=1 FOR UPDATE');$q->execute([$pid]);if(!$q->fetchColumn())throw new Exception('Select an active product.');check_platform_alignment($pid);om_assert_available($pid,$qty);om_assert_available($pid,$qty,$platform);$u=current_user();
  if(borrow_multiple_ready()){$prior=db()->prepare('SELECT id FROM borrowed_items WHERE borrow_ref=? OR batch_ref=? FOR UPDATE');$prior->execute([$ref,$ref]);if($prior->fetchColumn())throw new Exception('This borrow reference has already been issued.');}
  db()->prepare('INSERT INTO borrowed_items(borrow_ref,product_id,source_platform,borrower,qty,issue_date,due_date,reason,user_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$ref,$pid,$platform,$borrower,$qty,$date,$due,$reason,$u['id']]);$id=(int)db()->lastInsertId();
  db()->prepare('INSERT INTO outflows(txn_date,platform,order_id,product_id,source_item,qty,type,dedupe_key,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$date,$platform,$ref,$pid,'Borrowed: '.$borrower,$qty,'Borrowed Issue',hash('sha256','borrow|'.$ref),$reason,$u['id']]);$out=(int)db()->lastInsertId();db()->prepare('UPDATE borrowed_items SET outflow_id=? WHERE id=?')->execute([$out,$id]);$negative=change_platform_stock($platform,$pid,-$qty,$ref,$date);check_platform_alignment($pid);
  db()->prepare('INSERT INTO borrowed_events(borrow_id,event_type,qty,reference_no,reason,user_id,txn_date) VALUES(?,?,?,?,?,?,?)')->execute([$id,'Issued',$qty,$ref,$reason,$u['id'],$date]);audit('Issue borrowed item','Borrow',$ref,$qty.' pcs deducted from '.$platform.'; borrower '.$borrower.'; due '.$due);return ['id'=>$id,'negative'=>$negative];
 });
}
function borrow_return($input){
 return process_transaction(function()use($input){$id=(int)($input['borrow_id']??0);$r=borrow_get($id,true);$good=whole_number($input['good_qty']??'','Good quantity',0);$damage=whole_number($input['damaged_qty']??'','Damaged quantity',0);$repack=whole_number($input['repackaging_qty']??'0','For Repackaging quantity',0);if($repack)packaging_require();$qty=$good+$damage+$repack;if($qty<1||$qty>borrow_outstanding($r))throw new Exception('Return quantity must be between 1 and the outstanding balance.');$date=process_date($input['txn_date']??'');if($date<$r['issue_date'])throw new Exception('Return date cannot precede issue date.');$reason=process_reason($input['reason']??'');$ref=trim($input['reference_no']??'');if(!preg_match('/^[A-Za-z0-9_-]{6,100}$/',$ref))throw new Exception('Invalid return reference. Refresh the form.');$uid=current_user()['id'];
  db()->prepare('SELECT id FROM products WHERE id=? FOR UPDATE')->execute([$r['product_id']]);check_platform_alignment($r['product_id']);
  db()->prepare('INSERT INTO borrowed_events(borrow_id,event_type,qty,good_qty,damaged_qty,reference_no,reason,user_id,txn_date) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$id,'Returned',$qty,$good,$damage,$ref,$reason,$uid,$date]);if($repack)db()->prepare('UPDATE borrowed_events SET repackaging_qty=? WHERE id=?')->execute([$repack,(int)db()->lastInsertId()]);
  if($good){db()->prepare('INSERT INTO inflows(txn_date,reference_no,source_name,source_platform,product_id,source_qty,source_uom,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$date,$ref,$r['borrower'],$r['source_platform'],$r['product_id'],$good,'pc',$good,'Borrowed Return',$r['borrow_ref'].'; '.$reason,$uid]);change_platform_stock($r['source_platform'],$r['product_id'],$good,$ref,$date);}
  if($damage)db()->prepare('INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,0,?,?)')->execute([$date,$r['source_platform'],$ref,$r['product_id'],$damage,'Damage / Leak','Borrowed Return','For Review','Borrowed Return',$r['borrow_ref'].'; '.$reason,$uid]);
  if($repack){db()->prepare('INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,0,?,?)')->execute([$date,$r['source_platform'],$ref,$r['product_id'],$repack,'For Repackaging','Borrowed Return','Pending','Borrowed Return',$r['borrow_ref'].'; '.$reason,$uid]);packaging_initialize((int)db()->lastInsertId());}
  db()->prepare('UPDATE borrowed_items SET returned_qty=returned_qty+? WHERE id=?')->execute([$qty,$id]);borrow_refresh_status($id);check_platform_alignment($r['product_id']);$meta=['reference_kind'=>'Return From Borrowed','condition'=>$repack?($good||$damage?'Mixed Conditions / For Repackaging':'For Repackaging'):($damage?($good?'Mixed Good / Damaged':'Damaged / Leak'):'Good Item'),'destination'=>$r['source_platform'],'borrow_id'=>$id,'borrow_ref'=>$r['borrow_ref'],'product_name'=>$r['name'],'master_sku'=>$r['master_sku'],'remarks'=>$reason];db()->prepare('INSERT INTO inflow_batches(batch_ref,batch_type,source_name,reference_no,txn_date,status,total_qty,result_json,user_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$ref,'Borrowed Return',$r['borrower'],$r['borrow_ref'],$date,'Confirmed',$qty,json_encode($meta),$uid]);audit('Return borrowed item','Borrow',$r['borrow_ref'],$good.' good pcs returned to '.$r['source_platform'].'; '.$damage.' damaged pcs and '.$repack.' For Repackaging pcs to Non-Sellable; reference '.$ref);return $id;
 });
}
function borrow_request_conversion($input){return process_transaction(function()use($input){$r=borrow_get((int)($input['borrow_id']??0),true);$qty=whole_number($input['qty']??'','Conversion quantity',1);if($qty>borrow_outstanding($r))throw new Exception('Conversion exceeds outstanding balance.');$pending=db()->prepare("SELECT COUNT(*) FROM borrowed_events WHERE borrow_id=? AND status='Pending'");$pending->execute([$r['id']]);if($pending->fetchColumn())throw new Exception('An approval is already pending for this borrow record.');$reason=process_reason($input['reason']??'');$ref=next_ref('BOR-CONVERT');db()->prepare('INSERT INTO borrowed_events(borrow_id,event_type,qty,reference_no,status,reason,user_id,txn_date) VALUES(?,?,?,?,?,?,?,?)')->execute([$r['id'],'Permanent Conversion',$qty,$ref,'Pending',$reason,current_user()['id'],date('Y-m-d')]);audit('Request borrow conversion','Borrow',$r['borrow_ref'],$qty.' pcs; '.$reason);return (int)$r['id'];});}
function borrow_approve_conversion($eventId){if(current_user()['role']!=='Admin')throw new Exception('Only an administrator can approve a permanent conversion.');return process_transaction(function()use($eventId){$q=db()->prepare('SELECT * FROM borrowed_events WHERE id=? FOR UPDATE');$q->execute([$eventId]);$event=$q->fetch();if(!$event||$event['event_type']!=='Permanent Conversion'||$event['status']!=='Pending')throw new Exception('Conversion is no longer pending approval.');access_assert_admin_approval($event['user_id']);$r=borrow_get($event['borrow_id'],true);if((int)$event['qty']>borrow_outstanding($r))throw new Exception('Outstanding balance changed. Review the request again.');db()->prepare("UPDATE borrowed_events SET status='Approved',approved_by=? WHERE id=?")->execute([current_user()['id'],$eventId]);db()->prepare('UPDATE borrowed_items SET converted_qty=converted_qty+? WHERE id=?')->execute([$event['qty'],$r['id']]);borrow_refresh_status($r['id']);audit('Approve borrow conversion','Borrow',$r['borrow_ref'],$event['qty'].' pcs permanently converted. No second stock deduction. '.$event['reason']);return (int)$r['id'];});}
function borrow_reject_conversion($eventId,$reason){if(current_user()['role']!=='Admin')throw new Exception('Administrator access required.');$reason=process_reason($reason);return process_transaction(function()use($eventId,$reason){$q=db()->prepare("SELECT * FROM borrowed_events WHERE id=? AND status='Pending' AND event_type='Permanent Conversion' FOR UPDATE");$q->execute([$eventId]);$r=$q->fetch();if(!$r)throw new Exception('Request is no longer pending.');db()->prepare("UPDATE borrowed_events SET status='Rejected',approved_by=?,reason=CONCAT(reason,?) WHERE id=?")->execute([current_user()['id'],'; Rejected: '.$reason,$eventId]);audit('Reject borrow conversion','Borrow',(string)$r['borrow_id'],$reason);return (int)$r['borrow_id'];});}
require_once __DIR__.'/borrowed_multi.php';
